import { NextResponse } from "next/server";
// DİKKAT: generated içinden değil, kendi oluşturduğun lib içinden çekiyoruz
import { prisma } from "@/src/lib/prisma"; 

export async function GET() {
  try {
    const docs = await prisma.scrumDocument.findMany({
      orderBy: { createdAt: "desc" },
    });
    return NextResponse.json(docs);
  } catch (error: any) {
    return NextResponse.json({ error: error.message }, { status: 500 });
  }
}

export async function POST(req: Request) {
  try {
    const body = await req.json();
    const { userId, titel, documentType, sprint, datum, ...content } = body;

    // Prisma nesnesi yüklenmiş mi kontrol et (Hata almamak için güvenlik önlemi)
    if (!prisma || !prisma.scrumDocument) {
      throw new Error("Prisma Client veya ScrumDocument modeli bulunamadı.");
    }

    if (!userId) {
      return NextResponse.json({ error: "Kullanıcı ID gerekli" }, { status: 401 });
    }

    const newDoc = await prisma.scrumDocument.create({
      data: {
        userId,
        titel: titel || "Yeni Belge",
        documentType: documentType || "release",
        sprint: parseInt(sprint) || 1,
        datum: datum || new Date().toLocaleDateString(),
        content: content, 
      },
    });

    return NextResponse.json(newDoc);
  } catch (error: any) {
    console.error("API HATASI:", error.message);
    return NextResponse.json({ error: error.message }, { status: 500 });
  }
}